import 'package:path_provider/path_provider.dart';
import 'dart:io';
import 'dart:convert';

class FileStorageService {
  Future<String> get _localPath async {
    final directory = await getApplicationDocumentsDirectory();
    return directory.path;
  }

  Future<File> _getFile(String filename) async {
    final path = await _localPath;
    return File('$path/$filename');
  }

  // 텍스트 파일 쓰기
  Future<File> writeText(String filename, String content) async {
    final file = await _getFile(filename);
    return file.writeAsString(content);
  }

  // 텍스트 파일 읽기
  Future<String> readText(String filename) async {
    try {
      final file = await _getFile(filename);
      return await file.readAsString();
    } catch (e) {
      return '';
    }
  }

  // JSON 데이터 저장
  Future<void> saveJson(String filename, Map<String, dynamic> data) async {
    final file = await _getFile(filename);
    await file.writeAsString(jsonEncode(data));
  }

  // JSON 데이터 읽기
  Future<Map<String, dynamic>?> loadJson(String filename) async {
    try {
      final file = await _getFile(filename);
      final content = await file.readAsString();
      return jsonDecode(content) as Map<String, dynamic>;
    } catch (e) {
      return null;
    }
  }

  // 파일 삭제
  Future<void> deleteFile(String filename) async {
    try {
      final file = await _getFile(filename);
      if (await file.exists()) {
        await file.delete();
      }
    } catch (e) {
      // 파일이 없어도 무시
    }
  }
}

import 'package:path_provider/path_provider.dart';
