class AndroidStorageService {
  // 외부 저장소 디렉토리 (Android만)
  Future<Directory?> getExternalDir() async {
    if (Platform.isAndroid) {
      return await getExternalStorageDirectory();
    }
    return null;
  }

  // 다운로드 디렉토리 (Android, iOS, macOS, Windows, Linux)
  Future<Directory?> getDownloadsDir() async {
    try {
      return await getDownloadsDirectory();
    } catch (e) {
      return null;
    }
  }

  // 외부 캐시 디렉토리들 (Android만, 여러 개 가능)
  Future<List<Directory>?> getExternalCacheDirs() async {
    if (Platform.isAndroid) {
      return await getExternalCacheDirectories();
    }
    return null;
  }

  // 특정 타입의 외부 저장소 (Android만)
