      return await getExternalStorageDirectories(type: type);
    }
    return null;
  }
}

import 'package:flutter/material.dart';
import 'package:path_provider/path_provider.dart';
import 'dart:io';
import 'dart:convert';

class UserDataManager {
  static const _userDataFile = 'user_data.json';
  static const _cachePrefix = 'cache_';

  // 사용자 데이터 저장 (문서 디렉토리)
  Future<void> saveUserData(Map<String, dynamic> data) async {
    final dir = await getApplicationDocumentsDirectory();
    final file = File('${dir.path}/$_userDataFile');
    await file.writeAsString(jsonEncode(data));
  }

  // 사용자 데이터 로드
  Future<Map<String, dynamic>?> loadUserData() async {
    try {
      final dir = await getApplicationDocumentsDirectory();
      final file = File('${dir.path}/$_userDataFile');
      if (await file.exists()) {
        final content = await file.readAsString();
        return jsonDecode(content);
      }
    } catch (e) {
      debugPrint('Error loading user data: $e');
    }
    return null;
  }

  // 캐시 저장 (캐시 디렉토리)
  Future<void> cacheData(String key, String data) async {
    final dir = await getApplicationCacheDirectory();
    final file = File('${dir.path}/$_cachePrefix$key');
    await file.writeAsString(data);
  }

  // 캐시 로드
  Future<String?> getCachedData(String key) async {
    try {
      final dir = await getApplicationCacheDirectory();
      final file = File('${dir.path}/$_cachePrefix$key');
      if (await file.exists()) {
        return await file.readAsString();
      }
    } catch (e) {
      debugPrint('Error loading cache: $e');
    }
    return null;
  }

  // 캐시 전체 삭제
  Future<void> clearCache() async {
    final dir = await getApplicationCacheDirectory();
    if (await dir.exists()) {
      final files = dir.listSync();
      for (var file in files) {
        if (file is File && file.path.contains(_cachePrefix)) {
          await file.delete();
        }
      }
    }
  }

  // 저장소 사용량 계산
  Future<int> getStorageUsage() async {
    int totalSize = 0;
    final docDir = await getApplicationDocumentsDirectory();
    final cacheDir = await getApplicationCacheDirectory();

    totalSize += await _calculateDirSize(docDir);
    totalSize += await _calculateDirSize(cacheDir);

    return totalSize;
  }

  Future<int> _calculateDirSize(Directory dir) async {
    int size = 0;
    if (await dir.exists()) {
      await for (var entity in dir.list(recursive: true)) {
        if (entity is File) {
          size += await entity.length();
        }
      }
    }
    return size;
  }
}

// UI에서 사용
class StorageInfoWidget extends StatefulWidget {
  const StorageInfoWidget({super.key});

  @override
  State<StorageInfoWidget> createState() => _StorageInfoWidgetState();
}

class _StorageInfoWidgetState extends State<StorageInfoWidget> {
  final _dataManager = UserDataManager();
  Map<String, String> _paths = {};
  int _storageUsage = 0;

  @override
  void initState() {
    super.initState();
    _loadPaths();
  }

  Future<void> _loadPaths() async {
    final tempDir = await getTemporaryDirectory();
    final docDir = await getApplicationDocumentsDirectory();
    final cacheDir = await getApplicationCacheDirectory();
    final usage = await _dataManager.getStorageUsage();

    setState(() {
      _paths = {
        '임시 디렉토리': tempDir.path,
        '문서 디렉토리': docDir.path,
        '캐시 디렉토리': cacheDir.path,
      };
      _storageUsage = usage;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text('저장소 사용량: ${(_storageUsage / 1024).toStringAsFixed(2)} KB'),
        const SizedBox(height: 16),
        ..._paths.entries.map((e) => Padding(
          padding: const EdgeInsets.only(bottom: 8),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(e.key, style: const TextStyle(fontWeight: FontWeight.bold)),
              Text(e.value, style: const TextStyle(fontSize: 12)),
            ],
          ),
        )),
        ElevatedButton(
          onPressed: () async {
            await _dataManager.clearCache();
            await _loadPaths();
          },
          child: const Text('캐시 삭제'),
        ),
      ],
    );
  }
}
